import numpy as np

def select_next_node(cur_truck_pos, depot_pos, all_truck_pos, unvisited_customers):
    best_score = -np.inf
    best_node = 0

    for idx, cust in enumerate(unvisited_customers):
        dist_self = np.linalg.norm(cust - cur_truck_pos)

        # compute min distance to other trucks (excluding current) and depot
        min_other = np.linalg.norm(cust - depot_pos)
        for pos in all_truck_pos:
            if not np.array_equal(pos, cur_truck_pos):
                d = np.linalg.norm(cust - pos)
                if d < min_other:
                    min_other = d

        score = min_other - dist_self
        if score > best_score:
            best_score = score
            best_node = idx

    return best_node

import numpy as np

def select_next_node(cur_truck_pos, depot_pos, all_truck_pos, unvisited_customers):
    best_node = 0
    best_score = float('inf')
    other_trucks = [pos for pos in all_truck_pos if not np.array_equal(pos, cur_truck_pos)]

    for idx, cust in enumerate(unvisited_customers):
        d_cur = np.linalg.norm(cust - cur_truck_pos)
        if other_trucks:
            sum_other = sum(np.linalg.norm(cust - t) for t in other_trucks)
        else:
            sum_other = 1  # avoid division by zero
        score = d_cur / sum_other
        if score < best_score:
            best_score = score
            best_node = idx
    return best_node
